import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { int n = Integer.parseInt(br.readLine()); int[] a = new int[n]; StringTokenizer st = new StringTokenizer(br.readLine()); for (int i = 0; i < n; i++) { a[i] = Integer.parseInt(st.nextToken()); } int minMaxScore = Integer.MAX_VALUE; for (int i = 0; i < n; i++) { int currentMax = 0; if (i > 0) { currentMax = Math.max(currentMax, Math.abs(a[i] - a[i - 1])); } if (i < n - 1) { currentMax = Math.max(currentMax, Math.abs(a[i] - a[i + 1])); } minMaxScore = Math.min(minMaxScore, currentMax); } System.out.println(minMaxScore); } } }